package com.example.demo.service;

import java.util.List;
import java.util.Optional;

import org.springframework.stereotype.Service;

import com.example.demo.config.FeatureProperties;
import com.example.demo.entity.Customer;
import com.example.demo.repo.CustomerRepository;

@Service
public class CustomerService {

    private final CustomerRepository repository;
    private final FeatureProperties featureProperties;

    public CustomerService(CustomerRepository repository, FeatureProperties featureProperties) {
        this.repository = repository;
        this.featureProperties = featureProperties;
    }

    public List<Customer> findAll() {
        return repository.findAll();
    }

    public Optional<Customer> findById(Long id) {
        return repository.findById(id);
    }

    public Customer save(Customer customer) {
        return repository.save(customer);
    }

    public void deleteById(Long id) {
        repository.deleteById(id);
    }

    public String greet(Customer customer) {
        if (!featureProperties.isGreetingEnabled()) {
            return "";
        }
        return featureProperties.getGreetingPrefix() + ", " + customer.getName() + "!";
    }
}
